insert into public.conteudos (id, titulo, categoria, aba, resumo, corpo, fontes, ordem) values ('hidratacao', 'Hidratação: o quanto realmente importa', 'Segurança nos exercícios', 'Hoje', 'Quanto beber antes, durante e depois do treino — sem exagero.', '["Beber água parece óbvio, mas na prática é comum treinar meio desidratada sem perceber — e isso afeta desde o seu desempenho até a sua disposição no resto do dia. Não precisa virar obsessão: pequenos ajustes já fazem diferença.","Uma boa referência, usada pela Sociedade Brasileira de Medicina do Exercício e do Esporte, é beber entre 250 e 500 ml de água cerca de duas horas antes de treinar, e continuar bebendo aos poucos durante a sessão — principalmente se ela passar de uma hora. Depois do treino, o ideal é manter a hidratação ao longo do dia, não só naquele momento.","Para treinos de até uma hora (a maioria dos nossos), água já é suficiente. Em sessões muito mais longas, beber só água sem repor sal também não é saudável — mas isso é exceção, não a regra do dia a dia.","Se sentir sede intensa, tontura ou mal-estar durante o treino, pare e me avise — isso não é frescura, é seu corpo pedindo atenção."]'::jsonb, '[{"label":"Sociedade Brasileira de Medicina do Exercício e do Esporte (SBME) / ACSM — Exercise and Fluid Replacement, via Nutritotal PRO","url":"https://nutritotal.com.br/pro/qual-a-a-recomendaa-a-o-de-reposia-a-o-ha-drica-no-exerca-cio-fa-sico/"}]'::jsonb, 1)
insert into public.conteudos (id, titulo, categoria, aba, resumo, corpo, fontes, ordem) values ('sono', 'Sono: a parte do treino que ninguém vê', 'Constância', 'Mais', 'Por que dormir bem é parte do método, não um detalhe.', '["Todo mundo foca na hora do treino, mas boa parte do resultado acontece enquanto você dorme — é quando o corpo repara o músculo trabalhado. Dormir mal não anula o treino, mas atrapalha a recuperação e a disposição pros próximos dias.","Um estudo publicado na revista científica Nutrients, sobre práticas de sono e recuperação de atletas, aponta a faixa de 7 a 9 horas de sono por noite como referência para quem treina com regularidade — podendo ser ainda mais para quem treina intenso.","Na prática, ajuda manter um horário parecido pra dormir e acordar (inclusive no fim de semana), evitar tela cerca de uma hora antes de deitar, reduzir cafeína e álcool à noite, e deixar o quarto escuro, silencioso e fresco.","Se você tem insônia frequente, ronco alto ou cansaço que não melhora com o descanso, vale conversar com um médico ou especialista em sono — isso vai além do que posso te orientar como personal."]'::jsonb, '[{"label":"Estudo \"The Sleep and Recovery Practices of Athletes\" (Nutrients), via Tua Saúde","url":"https://www.tuasaude.com/news/2026/05/07/quantas-horas-de-sono-sao-necessarias-para-uma-recuperacao-muscular-eficaz/"}]'::jsonb, 2)
insert into public.conteudos (id, titulo, categoria, aba, resumo, corpo, fontes, ordem) values ('treino-seguro', 'Treino seguro: mitos e técnica', 'Segurança nos exercícios', 'Treinos', 'Por que treino de força não deixa mulher "volumosa", e como treinar com segurança.', '["Um dos medos mais comuns entre as mulheres que começam a treinar força é \"ficar grande\" ou \"muito volumosa\". Vale desfazer esse mito com calma, porque ele afasta muita gente de um treino que faz muito bem.","Mulheres têm bem menos testosterona circulante que homens, o que torna o ganho de massa muscular naturalmente mais lento e limitado. Um estudo com atletas mulheres, de 11 semanas, mostrou aumento real de força e uma aparência mais definida — sem o corpo ficar visivelmente volumoso. Os físicos muito musculosos de capa de revista vêm de anos de treino muito específico, volume muito alto e, em alguns casos, de recursos que não fazem parte do treino comum.","Sobre segurança: a técnica sempre vem antes da carga. Isso significa aquecer antes de um esforço mais intenso, aumentar o peso aos poucos — nunca de uma vez — e respeitar o tempo de descanso entre séries. Descansar também é parte do treino, não preguiça.","Cada corpo responde de um jeito, e é por isso que ajusto o treino de cada aluna com base no que ela me conta na avaliação inicial — não existe ficha genérica que sirva igual pra todo mundo."]'::jsonb, '[{"label":"Vikmoen et al., 2016, resumido por GetFitCraft — Fitness Myths Debunked","url":"https://getfitcraft.com/pt/blog/fitness-myths-debunked"},{"label":"American Council on Exercise (ACE) — Common Exercise Mistakes and Fixes","url":"https://www.acefitness.org/about-ace/press-room/press-releases/2481/american-council-on-exercise-shares-most-common-exericise-mistakes-and-fixes-to-avoid-them/"}]'::jsonb, 3)
insert into public.conteudos (id, titulo, categoria, aba, resumo, corpo, fontes, ordem) values ('habitos-alimentares', 'Hábitos alimentares, sem radicalismo', 'Constância', 'Mais', 'O que a diretriz oficial do Brasil recomenda — sem dieta e sem radicalismo.', '["Eu não prescrevo dieta — isso é trabalho de nutricionista, e cada corpo tem uma necessidade diferente. O que posso compartilhar é a orientação oficial do Ministério da Saúde pra população brasileira, que é simples e não exige radicalismo nenhum.","A \"regra de ouro\" do Guia Alimentar para a População Brasileira é direta: priorizar comida de verdade — arroz e feijão são o próprio exemplo que o documento usa — e evitar alimentos ultraprocessados, que estudos associam a mais risco de doenças cardiovasculares e outros problemas de saúde a longo prazo.","Isso não significa cortar tudo de uma vez ou viver de prato perfeito. É sobre direção: ir trocando um pouco mais de comida de verdade no lugar do ultraprocessado, no seu ritmo. Se quiser uma orientação mais específica pro seu objetivo, posso te indicar uma nutricionista de confiança."]'::jsonb, '[{"label":"Guia Alimentar para a População Brasileira — Ministério da Saúde, resumido pelo Conselho Federal de Nutricionistas (CFN)","url":"https://cfn.org.br/guia-alimentar-completa-dez-anos-por-que-o-documento-do-ministerio-da-saude-esta-mais-atual/"}]'::jsonb, 4)
insert into public.conteudos (id, titulo, categoria, aba, resumo, corpo, fontes, ordem) values ('forca-longevidade', 'Força e longevidade: o que a ciência diz', 'Longevidade', 'Evolução', 'Por que o treino de força é a aposta mais sólida pra quem pensa em se mover bem por muito mais tempo.', '["\"Movimento e Longevidade\" não é só um nome bonito — é uma aposta baseada no que a ciência do esporte vem mostrando, ano após ano. Treino de força aparece entre as dez tendências mais fortes do mundo em 17 dos últimos 20 anos, segundo o ranking anual do American College of Sports Medicine (ACSM), a maior entidade científica da área.","Para 2026, o ranking do ACSM coloca em destaque programas de exercício pra idade mais avançada — com foco em equilíbrio, massa muscular, força e mobilidade — e também o trabalho de equilíbrio e fluidez do corpo. Isso confirma algo que já é o centro do método: força não é sobre estética, é sobre continuar fazendo o que você gosta, com autonomia, daqui a 10, 20, 30 anos.","Uma referência internacional em treino pra mulheres na meia-idade, o Flipping 50, reforça que o treino dessa fase da vida precisa respeitar as mudanças do corpo e tratar recuperação — sono, mobilidade — como parte do treino, não como extra. É exatamente assim que cada aluna é acompanhada aqui."]'::jsonb, '[{"label":"ACSM — Top Fitness Trends for 2026","url":"https://acsm.org/top-fitness-trends-2026/"},{"label":"Flipping 50 — Fitness Trends for 2026, Midlife Women''s Edition","url":"https://www.flippingfifty.com/fitness-trends-for-2026"}]'::jsonb, 5)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('marcha-joelhos', 'Marcha com elevação de joelhos', 'Aquecimento', 'Marcha no lugar, subindo um joelho de cada vez e balançando os braços no ritmo.', '["Mantenha o tronco alto, sem jogar o corpo para trás.","Comece devagar e aumente o ritmo aos poucos."]'::jsonb, 'Se tiver dor no joelho ou no quadril, diminua a altura da perna.', 'marcha-joelhos', 1)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('agachamento', 'Agachamento livre', 'Pernas e glúteos', 'Pés na largura do quadril. Leve o quadril para trás e para baixo, como quem vai sentar numa cadeira, e volte empurrando o chão.', '["Os joelhos acompanham a direção dos pés.","Calcanhares sempre no chão.","Desça só até onde consegue manter a coluna firme."]'::jsonb, 'No começo, vale usar uma cadeira atrás de você como referência de altura.', 'agachamento', 2)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('ponte-gluteo', 'Ponte de glúteo', 'Pernas e glúteos', 'Deitada de barriga para cima, joelhos dobrados e pés no chão. Suba o quadril apertando o glúteo e desça com controle.', '["Empurre o chão com os calcanhares.","No alto, ombros, quadril e joelhos ficam alinhados."]'::jsonb, 'Não force a lombar para subir mais: quem sobe é o quadril.', 'ponte-gluteo', 3)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('flexao-inclinada', 'Flexão inclinada no banco', 'Peito e braços', 'Mãos apoiadas num banco firme, corpo reto da cabeça aos pés. Dobre os cotovelos levando o peito até o banco e volte.', '["Cotovelos apontam um pouco para trás, não para os lados.","Abdômen firme para o quadril não cair."]'::jsonb, 'Quanto mais alto o apoio, mais fácil. Uma parede também serve.', 'flexao-inclinada', 4)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('remada-curvada', 'Remada curvada com halteres', 'Costas', 'Joelhos levemente dobrados, tronco inclinado à frente com a coluna reta. Puxe os halteres em direção ao quadril e desça devagar.', '["Leve os cotovelos para trás, perto do corpo.","Aproxime as escápulas no final do movimento."]'::jsonb, 'Se sentir a lombar, diminua a inclinação do tronco ou apoie uma mão num banco.', 'remada-curvada', 5)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('terra-romeno', 'Levantamento terra romeno com halteres', 'Posterior e glúteos', 'Em pé, halteres à frente das coxas. Leve o quadril para trás deslizando os halteres pelas pernas e volte apertando o glúteo.', '["O movimento é do quadril, não da coluna.","Halteres sempre perto das pernas."]'::jsonb, 'Desça só até sentir alongar a parte de trás da coxa, sem arredondar as costas.', 'terra-romeno', 6)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('desenvolvimento', 'Desenvolvimento com halteres', 'Ombros', 'Halteres na altura dos ombros. Empurre para cima até estender os braços e desça com controle.', '["Costelas para baixo, sem arquear as costas.","Pode ser feito sentada, com encosto."]'::jsonb, 'Se tiver histórico de dor no ombro, avise antes de fazer este exercício.', 'desenvolvimento', 7)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('afundo', 'Afundo parado', 'Pernas e glúteos', 'Um pé à frente e outro atrás. Desça dobrando os dois joelhos e volte empurrando o pé da frente.', '["O tronco fica alto.","O joelho de trás vai em direção ao chão, sem bater."]'::jsonb, 'Para mais equilíbrio, apoie uma mão na parede.', 'afundo', 8)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('panturrilha', 'Elevação de panturrilha', 'Pernas', 'Em pé, suba na ponta dos pés e desça devagar até apoiar os calcanhares.', '["Suba o mais alto que conseguir, sem pressa.","Pode apoiar as mãos numa parede."]'::jsonb, 'Faça devagar se sentir câimbra.', 'panturrilha', 9)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('prancha', 'Prancha', 'Abdômen e core', 'Apoie antebraços e joelhos (versão mais leve) ou antebraços e pontas dos pés. Mantenha o corpo reto e respire.', '["Cotovelos embaixo dos ombros.","Não prenda a respiração."]'::jsonb, 'Se a lombar incomodar, volte para a versão com joelhos no chão.', 'prancha', 10)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('perdigueiro', 'Perdigueiro', 'Abdômen e core', 'Em quatro apoios, estenda um braço à frente e a perna oposta para trás. Volte e troque de lado.', '["Quadril parado, sem girar.","Pense em \"crescer\" para as duas pontas."]'::jsonb, 'Comece estendendo só a perna, se o equilíbrio ainda for difícil.', 'perdigueiro', 11)
insert into public.exercicios (id, nome, grupo, descricao, dicas, cuidado, animacao, ordem) values ('gato-camelo', 'Mobilidade gato-camelo', 'Mobilidade', 'Em quatro apoios, arredonde as costas olhando para o umbigo e depois afunde levemente a coluna olhando para a frente.', '["Movimento lento, junto com a respiração.","Use toda a coluna, do quadril ao pescoço."]'::jsonb, 'Faça numa amplitude confortável, sem dor.', 'gato-camelo', 12)
